	@ParameterizedTest(name = "autoRebuild={0}")
	@ValueSource(booleans = { false, true })
	void freshFormatSixKeepsItsExistingMarkedRebuildProtocol(boolean rebuild, @TempDir Path directory)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false)
				.setPredicateGuaranteeIndexAutoRebuild(rebuild);
		IRI predicate = VF.createIRI("urn:domain-freshness:integer");
		IRI subject = VF.createIRI("urn:domain-freshness:survivor");
		IRI removed = VF.createIRI("urn:domain-freshness:removed");
		IRI datePredicate = VF.createIRI("urn:domain-freshness:date");
		Literal ordinary = VF.createLiteral("7", XSD.INT);
		Literal noncanonical = VF.createLiteral("007", XSD.INT);
		Literal date = VF.createLiteral("0002-01-01", XSD.DATE);
		LmdbStore first = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(first);
		repository.init();
		RdfTermDomain before;
		try (RepositoryConnection connection = repository.getConnection()) {
			assertCurrentCapabilities(first, config);
			connection.begin();
			connection.add(subject, predicate, ordinary);
			connection.add(removed, predicate, noncanonical);
			connection.add(subject, datePredicate, date);
			connection.commit();
			connection.begin();
			connection.remove(removed, predicate, noncanonical);
			connection.commit();
			before = known(first, predicate).orElseThrow();
			assertTrue(before.has(RdfTermDomain.Fact.NUMBER));
			assertFalse(before.has(RdfTermDomain.Fact.CANONICAL_INTEGER));
		} finally {
			repository.shutDown();
		}
		LmdbStore second = new LmdbStore(directory.toFile(), config);
		repository = new SailRepository(second);
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			assertCurrentCapabilities(second, config);
			RdfTermDomain after = known(second, predicate).orElseThrow();
			assertEquals(rebuild, after.has(RdfTermDomain.Fact.CANONICAL_INTEGER));
			if (!rebuild) {
				assertEquals(before, after, "format6 equal-version OFF retains its committed broad guarantee");
			}
			assertTrue(after.hasDatatype(CoreDatatype.XSD.INT));
			assertTrue(admits(known(second, datePredicate).orElseThrow(), date));
			try (RepositoryResult<Statement> rows = connection.getStatements(null, null, null, false)) {
				Set<Statement> expected = Set.of(VF.createStatement(subject, predicate, ordinary),
						VF.createStatement(subject, datePredicate, date));
				List<Statement> actual = rows.stream().toList();
				assertEquals(2, actual.size());
				assertEquals(expected, Set.copyOf(actual));
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void assertCurrentCapabilities(LmdbStore store, LmdbStoreConfig config) {
		LmdbStoreFormat format = store.getFormat();
		assertEquals(LmdbStoreFormat.CURRENT_VERSION, format.getVersion());
		assertFalse(format.isLegacy());
		assertTrue(format.usesCoreDatatypeLiteralReferences());
		assertTrue(format.usesCanonicalLanguageTags());
		assertTrue(format.usesZeroFractionDateTimeIds());
		assertEquals(config.getOrderedNumericIds(), format.usesOrderedNumericIds());
	}

	private static Optional<RdfTermDomain> known(LmdbStore store, IRI predicate) throws IOException {
		ValueStore values = (ValueStore) store.getBackingStore().getValueFactory();
		return store.getBackingStore().getTripleStore().getKnownRdfTermDomain(values.getId(predicate));
	}

	private static boolean admits(RdfTermDomain domain, Value value) {
		// Existing exact finite-term/domain intersection API; no duplicate of the packed codec's private algorithm.
		return !domain.meetRequired(RdfTermDomain.finiteValues(List.of(value))).isEmpty();
	}

	private static void observeDomain(String name, Optional<RdfTermDomain> domain, Value value, List<String> output) {
		output.add(name + ".present\t" + domain.isPresent());
		domain.ifPresent(actual -> {
			output.add(name + ".mask\t" + Long.toUnsignedString(actual.mask()));
			output.add(name + ".maskHex\t" + Long.toUnsignedString(actual.mask(), 16));
			output.add(name + ".termIntersectionNonempty\t" + admits(actual, value));
			CoreDatatype.XSD datatype = actual.singleXsdDatatype();
			output.add(name + ".singleXsdDatatype\t" + (datatype == null ? "absent" : datatype.name()));
		});
	}

	private static void extractFixture(Path extractionRoot) throws Exception {
		Path root = extractionRoot.toAbsolutePath().normalize();
		assertFalse(Files.exists(root, LinkOption.NOFOLLOW_LINKS), "fixture extraction target is new per invocation");
		Files.createDirectories(root);
		Set<String> extracted = new HashSet<>();
		InputStream resource = LmdbLegacyPredicateDomainFreshnessTest.class.getResourceAsStream(FIXTURE_RESOURCE);
		assertTrue(resource != null, "the packaged closed legacy profiles are available on the test classpath");
		try (ZipInputStream archive = new ZipInputStream(Objects.requireNonNull(resource))) {
			ZipEntry entry;
			while ((entry = archive.getNextEntry()) != null) {
				String member = entry.getName();
				assertFalse(entry.isDirectory(), "the fixture archive contains files only");
				assertTrue(FIXTURE_MEMBERS.contains(member), "unexpected fixture archive member: " + member);
				assertTrue(extracted.add(member), "duplicate fixture archive member: " + member);
				Path destination = root.resolve(member).normalize();
				assertTrue(destination.startsWith(root), "fixture archive member remains below its temp root");
				Files.createDirectories(destination.getParent());
				long expectedSize = expectedSize(member);
				assertEquals(expectedSize, entry.getSize(), "fixture member metadata size: " + member);
				try (var output = Files.newOutputStream(destination, StandardOpenOption.CREATE_NEW,
						StandardOpenOption.WRITE)) {
					byte[] buffer = new byte[8192];
					long copied = 0;
					int read;
					while ((read = archive.read(buffer)) != -1) {
						copied += read;
						assertTrue(copied <= expectedSize, "fixture member is bounded by its reviewed size: " + member);
						output.write(buffer, 0, read);
					}
					assertEquals(expectedSize, copied, "fixture member byte count: " + member);
				}
				archive.closeEntry();
			}
		}
		assertEquals(FIXTURE_MEMBERS, extracted, "the archive contains the exact two-profile fixture set");
		authenticate(root.resolve("inline-false"), false);
		authenticate(root.resolve("inline-true"), true);
	}

	private static long expectedSize(String member) {
		String profileFile = member.substring(member.indexOf('/') + 1);
		return PROFILE_SIZES.get(PROFILE_FILES.indexOf(profileFile));
	}

	private static void authenticate(Path original, boolean inline) throws Exception {
		assertTrue(Files.isDirectory(original, LinkOption.NOFOLLOW_LINKS));
		List<String> hashes = inline ? INLINE_TRUE_HASHES : INLINE_FALSE_HASHES;
		try (Stream<Path> entries = Files.walk(original)) {
			Set<String> actual = entries.filter(path -> !Files.isDirectory(path, LinkOption.NOFOLLOW_LINKS))
					.map(original::relativize)
					.map(Path::toString)
					.map(path -> path.replace('\\', '/'))
					.collect(Collectors.toSet());
			assertEquals(Set.copyOf(PROFILE_FILES), actual,
					"the closed profile contains exactly four authenticated corpus files");
		}
		for (int index = 0; index < PROFILE_FILES.size(); index++) {
			Path file = original.resolve(PROFILE_FILES.get(index));
			assertTrue(Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS));
			assertEquals(PROFILE_SIZES.get(index).longValue(), Files.size(file),
					"closed evidence file size must remain unchanged: " + PROFILE_FILES.get(index));
			String actual = HexFormat.of()
					.formatHex(MessageDigest.getInstance("SHA-256")
							.digest(Files.readAllBytes(file)));
			assertEquals(hashes.get(index), actual,
					"closed evidence file must remain unchanged: " + PROFILE_FILES.get(index));
		}
	}
